import type { IngredientResolution, ResolutionProvenance, ResolvedMealIngredient } from '@motivation/shared';

/**
 * How an ingredient/food was bound (your library / OFF / AI-generated) — the
 * actionable signal that replaced the old confidence bucket. Shared by the
 * single-food result (in `ai-estimate.component`) and the multi-ingredient
 * result (`ai-meal-result`), which is why it lives in its own module rather
 * than on either component.
 */
const PROVENANCE_LABELS: Record<ResolutionProvenance, { label: string; cls: string }> = {
    matched_library: { label: '📚 library', cls: 'provenance-library' },
    matched_off: { label: '🛒 OFF', cls: 'provenance-off' },
    generated: { label: '🤖 AI', cls: 'provenance-generated' },
};

export function createProvenanceBadge(resolution: ResolvedMealIngredient): HTMLSpanElement {
    const { label, cls } = PROVENANCE_LABELS[resolution.provenance];
    const badge = document.createElement('span');
    badge.className = `provenance-badge ${cls}`;
    badge.textContent = label;
    badge.title = resolution.similarity !== null
        ? `${resolution.tier} match (${Math.round(resolution.similarity * 100)}%)`
        : resolution.tier;
    return badge;
}

/**
 * Story 319 — several library rows share this ingredient's canonical name and
 * they disagree about calories, so the bound row was picked on how often it
 * was logged, which says nothing about which one is right. Show the spread
 * rather than resolve it silently; null when the siblings agree (or there are
 * none), which is the common case.
 */
export function createDivergenceBadge(resolution: IngredientResolution): HTMLSpanElement | null {
    const { divergence } = resolution;
    if (!divergence) return null;
    const badge = document.createElement('span');
    badge.className = 'provenance-badge divergence-badge';
    badge.textContent = `⚠ ${Math.round(divergence.kcal_min)}–${Math.round(divergence.kcal_max)} kcal/100g`;
    // Not "…and disagree": a sibling with no comparable kcal still shares the
    // name and is counted here, while the range beside it covers only the rows
    // that could be compared.
    badge.title = `${divergence.sibling_count} library rows share this name — the most-logged one was used.`;
    return badge;
}
